-- Enseres pasa al carrusel de piezas: una cada vez, con la foto grande y, al
-- lado, su familia, su nombre, su historia y su cartela. Arriba, un párrafo de
-- entrada con el texto de partida.
--
-- OJO: las piezas, autores, talleres y años son DE EJEMPLO, y las fotos, de
-- otras hermandades (Wikimedia Commons, CC BY-SA). Hay que cambiarlos por los
-- del Grupo en el CMS antes de publicar la web.
--
-- Solo se sustituye la página que sigue con el texto de partida: si alguien ya
-- la ha editado en el CMS, se queda como está.

UPDATE `ContenidoPagina` SET `datos` = '{"cabecera":{"titulo":"Enseres","subtitulo":"El patrimonio del Grupo Parroquial, pieza a pieza.","foto":"","fotoAlt":""},"bloques":[{"tipo":"texto","titulo":"","html":"<p>Los enseres procesionales son elementos fundamentales que acompañan al Grupo Parroquial en la calle. El cuidado de los enseres es tarea de todos los hermanos, conscientes de que estos objetos no son meros adornos, sino signos visibles de una identidad cofrade que se transmite de generación en generación con respeto y cariño.</p>"},{"tipo":"carrusel","titulo":"","piezas":[{"familia":"Insignias","titulo":"Cruz de guía","texto":"Abre el cortejo y marca el camino. Madera forrada de metal dorado, con los atributos de la Pasión en relieve.","foto":{"url":"/images/enseres/cruz.webp","alt":"Cruz de guía dorada, con los atributos de la Pasión en relieve","pie":"Foto de ejemplo · Wikimedia Commons, CC BY-SA"},"datos":[{"etiqueta":"Autor","valor":"Orfebrería Hermanos Lozano"},{"etiqueta":"Año","valor":"1997"},{"etiqueta":"Materiales","valor":"Madera, metal dorado"}]},{"familia":"Insignias","titulo":"Estandarte corporativo","texto":"La insignia que representa al Grupo. Bordado en oro sobre terciopelo morado, con el Crucificado en el óvalo central.","foto":{"url":"/images/enseres/estandarte.webp","alt":"Estandarte morado bordado en oro, con un crucificado en el centro","pie":"Foto de ejemplo · Wikimedia Commons, CC BY-SA"},"datos":[{"etiqueta":"Bordado","valor":"Taller de bordado de la Esperanza"},{"etiqueta":"Año","valor":"2004"},{"etiqueta":"Materiales","valor":"Terciopelo, oro fino"}]},{"familia":"Insignias","titulo":"Simpecado","texto":"Precede al trono de la Virgen. Terciopelo granate bordado en oro, con la imagen de la Señora pintada al óleo.","foto":{"url":"/images/enseres/simpecado.webp","alt":"Simpecado granate bordado en oro, con la Virgen pintada en el centro","pie":"Foto de ejemplo · Wikimedia Commons, CC BY-SA"},"datos":[{"etiqueta":"Bordado","valor":"Hermanas camareras"},{"etiqueta":"Año","valor":"2011"},{"etiqueta":"Procedencia","valor":"Donación"}]},{"familia":"Archivo","titulo":"Libro de Reglas","texto":"Guarda las reglas aprobadas por el Obispado. Tapas de terciopelo con cantoneras y escudo en plata de ley.","foto":{"url":"/images/enseres/reglas.webp","alt":"Tapas de terciopelo azul con cantoneras y escudo de plata","pie":"Foto de ejemplo · Wikimedia Commons, CC BY-SA"},"datos":[{"etiqueta":"Orfebre","valor":"Talleres Marín"},{"etiqueta":"Año","valor":"1989"},{"etiqueta":"Materiales","valor":"Terciopelo, plata de ley"}]},{"familia":"Orfebrería","titulo":"Incensario y naveta","texto":"El humo del incienso abre paso a la Virgen. Incensario y naveta de metal plateado, cincelados a mano.","foto":{"url":"/images/enseres/incensario.webp","alt":"Incensario humeante y naveta de plata, con sus cadenas","pie":"Foto de ejemplo · Wikimedia Commons, CC BY-SA"},"datos":[{"etiqueta":"Orfebre","valor":"Orfebrería Hermanos Lozano"},{"etiqueta":"Año","valor":"2015"}]},{"familia":"Bordado","titulo":"Manto de salida","texto":"Hojarasca de oro sobre terciopelo negro. Se restauró en 2018 y se pasó a terciopelo nuevo.","foto":{"url":"/images/enseres/manto.webp","alt":"Detalle del bordado en oro del manto, con flores y hojas sobre terciopelo negro","pie":"Foto de ejemplo · Wikimedia Commons, CC BY-SA"},"datos":[{"etiqueta":"Bordado","valor":"Taller de bordado de la Esperanza"},{"etiqueta":"Año","valor":"1976, restaurado en 2018"},{"etiqueta":"Materiales","valor":"Terciopelo, oro fino"}]},{"familia":"Trono","titulo":"Palio y candelería","texto":"Doce varales y candelería de metal plateado: la luz de la cera sobre la Virgen, el Sábado de Pasión.","foto":{"url":"/images/enseres/palio.webp","alt":"Palio de noche, con la candelería encendida delante de la Virgen","pie":"Foto de ejemplo · Wikimedia Commons, CC BY-SA"},"datos":[{"etiqueta":"Orfebre","valor":"Talleres Marín"},{"etiqueta":"Año","valor":"2021"},{"etiqueta":"Piezas","valor":"12 varales, 64 candeleros"}]},{"familia":"Trono","titulo":"Trono de la Virgen","texto":"La pieza mayor del Grupo. Caoba, metal plateado, jarras y candelería, portado por su cuadrilla.","foto":{"url":"/images/trono-candeleria.webp","alt":"El trono de la Virgen de los Desamparados, con la candelería","pie":""},"datos":[{"etiqueta":"Autor","valor":"Talleres Marín"},{"etiqueta":"Año","valor":"2008"},{"etiqueta":"Materiales","valor":"Caoba, metal plateado"}]}]}]}'
WHERE `slug` = 'enseres' AND `datos` LIKE '%Los enseres procesionales son elementos fundamentales%' AND `datos` NOT LIKE '%"tipo":"carrusel"%';
